/* === grouped nav dropdown toggle (added) === */
(function(){
  var dds=[].slice.call(document.querySelectorAll('.nav-dd'));
  if(!dds.length) return;
  dds.forEach(function(dd){
    var btn=dd.querySelector('.nav-dd-btn'); if(!btn) return;
    btn.addEventListener('click',function(e){
      e.preventDefault();
      var open=dd.classList.contains('open');
      dds.forEach(function(d){d.classList.remove('open');var b=d.querySelector('.nav-dd-btn');if(b)b.setAttribute('aria-expanded','false');});
      if(!open){dd.classList.add('open');btn.setAttribute('aria-expanded','true');}
    });
  });
  document.addEventListener('click',function(e){ if(!e.target.closest('.nav-dd')){dds.forEach(function(d){d.classList.remove('open');var b=d.querySelector('.nav-dd-btn');if(b)b.setAttribute('aria-expanded','false');});} });
  document.addEventListener('keydown',function(e){ if(e.key==='Escape'){dds.forEach(function(d){d.classList.remove('open');});} });
})();
